CREATE TABLE usuarios(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(255) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL);CREATE TABLE roles(nombre VARCHAR(30) PRIMARY KEY);INSERT INTO roles VALUES ('ADMIN'),('CLIENTE');CREATE TABLE usuario_roles(usuario_id BIGINT NOT NULL REFERENCES usuarios(id),rol VARCHAR(30) NOT NULL REFERENCES roles(nombre),PRIMARY KEY(usuario_id,rol));